            res = self._import_targets(item.path, item.static, item.wildcard) or None
            edges.append(edge("imports", file.owners[0], res, Use(item.path, item.start, item.end)))

        # A declaration's modifiers lie in its parent scope (java._Facts._open) yet are its own.
        heads: dict[int, list[tuple[int, int, int]]] = {}
        for k, scope in enumerate(file.parsed.scopes):
            if k and scope.decl is not None and scope.parent is not None:
                heads.setdefault(scope.parent, []).append((scope.decl.start, scope.decl.end, k))

        def owner(k: int, at: int) -> str:
            row = heads.get(k, [])
            j = bisect.bisect_right(row, (at + 1,)) - 1
            return file.owners[row[j][2] if j >= 0 and at < row[j][1] else k]

        for k, scope in enumerate(file.parsed.scopes):
            key = file.keys[k]
            if k and key is not None and scope.decl is not None:
                d = scope.decl
                at = evidence(d.start, d.end)
                entities.append(Entity(key, "symbol", d.kind, d.name, d.signature, at, d.test))
                edges.append(structural("contains", file.owners[scope.parent or 0], key, None))
                if scope.parent == 0 and file.package[1]:
                    edges.append(structural("defines", module_key(file.package[1]), key, at))
            for ref in scope.refs:
                found = self._type(i, k, ref.name)
                source = owner(k, ref.start)
                edges.append(edge("references", source, self._keys(found or []) or None, ref))
            for call in scope.calls:
                found = self._call(i, k, call)
                source = owner(k, call.start)
                relation = edge("calls", source, self._keys(found or []) or None, call)
                callee = relation.targets[0] if relation.resolution == "resolved" else None
                if source in self.tests and callee and callee not in self.tests:
                    at = evidence(call.start, call.end)
                    edges.append(
                        Edge("tested_by", callee, (source,), "resolved", "heuristic", None, at)
                    )
                edges.append(relation)

    return "" if node is None else data[node.start_byte : node.end_byte].decode("utf-8", "replace")


def _dotted(data: bytes, node: Node | None) -> str:
    return "".join(_text(data, node).split())


def _named(node: Node | None) -> list[Node]:
    return [] if node is None else [c for c in node.named_children if c.type not in _COMMENTS]


def type_name(data: bytes, node: Node | None) -> str | None:
    """The dotted class or interface a type node names, without type arguments; None
    for ``var``, primitives, arrays and anything else."""
    while node is not None and node.type in ("generic_type", "annotated_type"):
        named = [c for c in _named(node) if c.type != "type_arguments"]
        node = named[0 if node.type == "generic_type" else -1] if named else None
    if node is None or node.type not in ("type_identifier", "scoped_type_identifier"):
        return None
    name = _dotted(data, node)
    return None if name == "var" else name


def _annotations(node: Node) -> list[Node]:
    kinds = ("marker_annotation", "annotation")
    return [
        a for m in node.children if m.type == "modifiers" for a in m.children if a.type in kinds
    ]


def _signature(data: bytes, node: Node, end: int) -> str:
    """The header up to ``end``, without annotations, whitespace collapsed."""
    pieces, at = [], node.start_byte
    for a in _annotations(node):
        pieces.append(data[at : a.start_byte])
        at = a.end_byte
    pieces.append(data[at:end])
    return " ".join(b"".join(pieces).decode("utf-8", "replace").split()).removesuffix(";")


def _path(node: Node) -> bool:
    """``this.x`` or ``a.b.c``: a field access of identifiers, or of ``this`` and one."""
    first = True
    while node.type == "field_access":
        inner, member = node.child_by_field_name("object"), node.child_by_field_name("field")
        if inner is None or member is None or member.type != "identifier":
            return False
        if inner.type == "this":
            return first
        node, first = inner, False
    return node.type == "identifier"


def _span(node: Node) -> tuple[int, int]:
    return node.start_byte, node.end_byte


class _Facts:
    def __init__(self, data: bytes) -> None:
        self.data = data
        self.scopes = [Scope(None, None)]
        self.nesting = Nesting(len(data))
        self.headers: dict[int, list[tuple[int, int]]] = {}  # type scope -> header clause spans
        self.created: set[int] = set()  # start bytes of instance creation types

    def scope_at(self, at: int) -> int:

def scope_at(self, at: int) -> int:
    return self.nesting.scope_at(at)

def _open(self, parent: int, scope: Scope, span: Node) -> None:
    # Past the modifiers: javac resolves a declaration's annotations in the enclosing scope.
    start = next((c.start_byte for c in span.children if c.type != "modifiers"), span.end_byte)
    self.scopes.append(scope)
    self.nesting.add(parent, (start, span.end_byte))

def _is_type(self, k: int) -> bool:
    decl = self.scopes[k].decl
    return decl is not None and decl.kind in TYPE_KINDS

def type(self, node: Node) -> None:
    data, parent = self.data, self.scope_at(node.start_byte)
    name, body = node.child_by_field_name("name"), node.child_by_field_name("body")
    if name is None or body is None:
        return
    supers = []
    # javac resolves these in the enclosing scope (a record's components see its members).
    header = [_span(c) for c in node.children if c.type in _HEADER]
    self.headers[len(self.scopes)] = header
    for clause in node.children:
        if clause.type == "superclass":
            listed = _named(clause)
        elif clause.type in ("super_interfaces", "extends_interfaces"):
            listed = [t for c in _named(clause) for t in _named(c)]
        else:
            continue
        for t in listed:
            if (base := type_name(data, t)) is not None:
                supers.append(Use(base, *_span(t)))
    if parent and not self._is_type(parent):  # a local class
        self.scopes[parent].types.add(_text(data, name))
        self._open(parent, Scope(parent, None, supers), node)
        return
    signature = _signature(data, node, body.start_byte)
    kind = _TYPE_KINDS[node.type]
    decl = Decl(kind, _text(data, name), *_span(node), signature, 0, False, False)
    self._open(parent, Scope(parent, decl, supers), node)

def member(self, node: Node) -> None:
    data, parent = self.data, self.scope_at(node.start_byte)
    name = node.child_by_field_name("name")
    if name is None or not self._is_type(parent):
        return  # a member of a local or anonymous class: part of that scope
    body = node.child_by_field_name("body")
    params = [
        p
        for p in _named(node.child_by_field_name("parameters"))
        if p.type in ("formal_parameter", "spread_parameter")
    ]
    method = node.type in ("method_declaration", "annotation_type_element_declaration")
    decl = Decl(
        "method" if method else "constructor",
        _text(data, name),
        *_span(node),
        _signature(data, node, body.start_byte if body else node.end_byte),
        len(params),
        any(p.type == "spread_parameter" for p in params),
        method
        and any(
            _dotted(data, a.child_by_field_name("name")).rpartition(".")[2] in TEST_ANNOTATIONS
            for a in _annotations(node)
        ),
    )
    self._open(parent, Scope(parent, decl), node)

def anonymous(self, body: Node, base: str | None) -> None:
    parent = self.scope_at(body.start_byte)
    supers = [Use(base, body.start_byte, body.start_byte)] if base else []

        supers = [Use(base, body.start_byte, body.start_byte)] if base else []
        self._open(parent, Scope(parent, None, supers), body)

    def bind(self, name: Node | None, kind: str | None) -> None:
        if name is None:
            return
        bound, text = self.scopes[self.scope_at(name.start_byte)].bound, _text(self.data, name)
        bound[text] = kind if bound.get(text, kind) == kind else None

    def variable(self, node: Node) -> None:
        data = self.data
        if node.type in ("type_pattern", "record_pattern_component"):
            parts = _named(node)
            if len(parts) == 2 and parts[1].type == "identifier":
                self.bind(parts[1], type_name(data, parts[0]))
            return
        name = node.child_by_field_name("name")
        if node.type == "catch_formal_parameter":
            caught = next((c for c in node.named_children if c.type == "catch_type"), None)
            types = _named(caught)
            self.bind(name, type_name(data, types[0]) if len(types) == 1 else None)
            return
        kind = node.child_by_field_name("right" if node.type == "instanceof_expression" else "type")
        array = node.child_by_field_name("dimensions") is not None
        self.bind(name, None if array else type_name(data, kind))

    def variables(self, node: Node) -> None:
        kind = type_name(self.data, node.child_by_field_name("type"))
        for declarator in node.children_by_field_name("declarator"):
            array = declarator.child_by_field_name("dimensions") is not None
            self.bind(declarator.child_by_field_name("name"), None if array else kind)

    def call(self, node: Node) -> None:
        data, name = self.data, node.child_by_field_name("name")
        receiver = node.child_by_field_name("object")
        if name is None:
            return
        if receiver is None:
            form = ""
        elif receiver.type in ("this", "super", "identifier") or _path(receiver):
            form = _dotted(data, receiver) + "."
        else:
            return  # a call on an expression's value: needs its type
        arity = len(_named(node.child_by_field_name("arguments")))
        self.use(Call(form + _text(data, name), node.start_byte, name.end_byte, arity))

    def new(self, node: Node) -> None:
        kind = node.child_by_field_name("type")
        if kind is None or not node.children or node.children[0].type != "new":
            return  # ``outer.new Inner()``: needs the outer value's type
        base = type_name(self.data, kind)
        if base is not None:
            self.created.add(kind.start_byte)
            arity = len(_named(node.child_by_field_name("arguments")))
            self.use(Call(f"new {base}", node.start_byte, kind.end_byte, arity))

    def use(self, call: Call) -> None:
        self.scopes[self.scope_at(call.start)].calls.append(call)


def _body(node: Node, what: str) -> Node:
    """The node a scope spans: an anonymous class's body, else the declaration."""
    if what != "anonymous":
        return node
    return next(c for c in reversed(node.named_children) if c.type == "class_body")


def parse(data: bytes) -> Parsed | str:
    """Syntax facts, or the reason the file is unsupported."""
    try:
        data.decode("utf-8")

    data.decode("utf-8")
except UnicodeDecodeError:
    return "Java source is not UTF-8"
root = Parser(LANGUAGE).parse(data).root_node
if too_deep(root):
    return TOO_DEEP
captures = QueryCursor(_QUERY).captures(root)
facts = _Facts(data)
openers = ("type", "member", "anonymous", "constant_body")
opening = [(_body(n, what), n, what) for what in openers for n in captures.get(what, [])]
for body, node, what in sorted(opening, key=lambda o: o[0].start_byte):  # parents first
    if what == "type":
        facts.type(node)
    elif what == "member":
        facts.member(node)
    elif what == "anonymous":
        facts.anonymous(body, type_name(data, node.child_by_field_name("type")))
    else:
        enum = facts.scopes[facts.scope_at(node.start_byte)].decl
        facts.anonymous(node, enum.name if enum is not None else None)
scopes = facts.scopes
for node in captures.get("type_parameter", []):
    scopes[facts.scope_at(node.start_byte)].types.add(_text(data, node))
for node in captures.get("constant", []):
    enum = scopes[facts.scope_at(node.start_byte)].decl
    facts.bind(node, enum.name if enum is not None else None)
for node in captures.get("var", []):
    facts.variable(node)
for node in captures.get("vars", []):
    facts.variables(node)
for node in captures.get("untyped", []):
    facts.bind(node, None)
for node in captures.get("call", []):
    facts.call(node)
for node in captures.get("new", []):
    facts.new(node)
# Type parameter declarations, and instance creations (calls of the class).
skip = {n.start_byte for n in captures.get("type_parameter", [])} | facts.created
reach = -1
for node in sorted(captures.get("ref", []), key=lambda n: (n.start_byte, -n.end_byte)):
    if node.start_byte < reach:
        continue  # a part of a qualified type already seen
    reach = node.end_byte
    if node.start_byte not in skip and (name := _dotted(data, node)) != "var":
        k = facts.scope_at(node.start_byte)
        header = any(s <= node.start_byte < e for s, e in facts.headers.get(k, ()))
        if header and name.split(".")[0] not in scopes[k].types:  # but sees its type parameters
            k = scopes[k].parent or 0
        scopes[k].refs.append(Use(name, *_span(node)))
imports = []
for node in captures.get("import", []):
    path = next((c for c in node.named_children if c.type.endswith("identifier")), None)
    if path is not None:
        kinds = {c.type for c in node.children}
        imports.append(
            Import("static" in kinds, _dotted(data, path), "asterisk" in kinds, *_span(node))
        )
imports.sort(key=lambda item: (item.start, item.end))
for scope in scopes:
    scope.calls.sort(key=lambda u: (u.start, u.end))
    scope.refs.sort(key=lambda u: (u.start, u.end))
package = min(captures.get("package", []), key=lambda n: n.start_byte, default=None)
return Parsed(_dotted(data, package), imports, scopes, syntax_diagnostics(root, _BROKEN))

def _is_type(scope: Scope) -> bool:
    """A declared type or a local or anonymous class body."""
    return scope.parent is not None and (scope.decl is None or scope.decl.kind in TYPE_KINDS)


def _fits(method: Scope, arity: int) -> bool:
    d = method.decl
    return d is not None and (arity == d.arity or (d.varargs and arity >= d.arity - 1))


class Resolver:
    def __init__(self, files: list[tuple[str, str, Parsed]]) -> None:
        self.files: list[_File] = []
        self.packages: dict[Package, list[int]] = {}
        self.tops: dict[Package, dict[str, list[Site]]] = {}  # top-level types by name
        self.children: dict[Site, dict[str, list[int]]] = {}  # declared members by name
        self.supers: dict[Site, tuple[list[Site], bool]] = {}  # memo: (captured, complete)
        self.tests: set[str] = set()
        for path, digest, parsed in files:
            i, keys = len(self.files), symbol_keys(path, parsed)
            package = ("", parsed.package) if parsed.package else (path.rpartition("/")[0], "")
            owners = [str(keys[0])]
            for k, s in enumerate(parsed.scopes[1:], 1):
                owners.append(keys[k] or owners[s.parent or 0])
                if s.decl is None or s.parent is None:
                    continue
                self.children.setdefault((i, s.parent), {}).setdefault(s.decl.name, []).append(k)
                if s.parent == 0:
                    self.tops.setdefault(package, {}).setdefault(s.decl.name, []).append((i, k))
                if s.decl.test:
                    self.tests.add(owners[k])
            self.files.append(_File(path, digest, parsed, keys, owners, package))
            self.packages.setdefault(package, []).append(i)
        for file in self.files:
            self._bind_imports(file)

    # --- types ---

    def _scope(self, site: Site) -> Scope:
        return self.files[site[0]].parsed.scopes[site[1]]

    def _declared(self, site: Site, name: str, kinds: frozenset[str]) -> list[Site]:
        scopes = self.files[site[0]].parsed.scopes
        return [
            (site[0], k)
            for k in self.children.get(site, {}).get(name, [])
            if (d := scopes[k].decl) is not None and d.kind in kinds
        ]

    def _canonical(self, dotted: str) -> list[Site]:
        """A fully qualified type: the longest captured package prefix, then members."""
        parts = dotted.split(".")
        for cut in range(len(parts) - 1, 0, -1):
            found = self.tops.get(("", ".".join(parts[:cut])), {}).get(parts[cut], [])
            if found:
                return self._nested(found, parts[cut + 1 :])
        return []

    def _nested(self, sites: list[Site], names: list[str]) -> list[Site]:
        for name in names:
            sites = sorted({m for s in sites for m in self._member_types(s, name, set())})
        return sites

    def _member_types(self, site: Site, name: str, seen: set[Site]) -> list[Site]:
        """Member types ``name``, declared or inherited from captured supertypes (one
        outside the capture is assumed to declare none: docs/java.md § Not modeled)."""
        found = self._declared(site, name, TYPE_KINDS)
        if found or site in seen:
            return found
        seen.add(site)
        inherited = {
            m for s in self._supertypes(site)[0] for m in self._member_types(s, name, seen)
        }
        return sorted(inherited)

    return sorted(inherited)

def _supertypes(self, site: Site) -> tuple[list[Site], bool]:
    """Captured direct supertypes, and whether every named one is captured (a cycle
    or an ambiguous name leaves the hierarchy incomplete)."""
    if site in self.supers:
        return self.supers[site]
    self.supers[site] = ([], False)  # in progress: a cycle is unknown
    scope = self._scope(site)
    found: list[Site] = []
    complete = True
    for use in scope.supers:
        sites = self._type(site[0], scope.parent or 0, use.name)
        if sites is not None and len(sites) == 1:
            found.append(sites[0])
        else:
            complete = False
    self.supers[site] = (found, complete)
    return found, complete

def _type(self, i: int, k: int, dotted: str) -> Found:
    """The types a (possibly qualified) type name denotes in scope ``k`` of file ``i``."""
    first, *rest = dotted.split(".")
    found = self._simple(i, k, first)
    if found:
        return self._nested(found, rest) or None
    return (self._canonical(dotted) or None) if rest else found

def _simple(self, i: int, k: int, name: str) -> Found:
    file = self.files[i]
    scopes = file.parsed.scopes
    while k:
        scope = scopes[k]
        if name in scope.types:
            return None  # a type parameter or local class
        if _is_type(scope) and (found := self._member_types((i, k), name, set())):
            return found
        k = scope.parent or 0
    found = self._declared((i, 0), name, TYPE_KINDS)
    if found:
        return found
    if name in file.single:
        return file.single[name] or None  # an import outside the capture shadows too
    found = self.tops.get(file.package, {}).get(name, [])
    if found:
        return found
    demand = {
        site
        for target in file.demand
        for site in (
            self.tops.get(("", target), {}).get(name, [])
            if isinstance(target, str)
            else self._member_types(target, name, set())
        )
    }
    return sorted(demand) or None

# --- members ---

def _methods(self, site: Site, name: str, arity: int, done: dict[Site, Found]) -> Found:
    """Methods ``name`` of a type accepting ``arity`` arguments, from the nearest
    declaring type of its captured hierarchy; [] when it certainly has none. ``done``
    memoizes each type, so a diamond reuses a finished branch and a cycle is None."""
    if site not in done:
        done[site] = None  # in progress: reaching it again is a cycle
        done[site] = self._own_methods(site, name, arity, done)
    return done[site]

def _own_methods(self, site: Site, name: str, arity: int, done: dict[Site, Found]) -> Found:
    scope = self._scope(site)
    if scope.decl is None:
        return None  # a local or anonymous class's members are not facts
    own = self._declared(site, name, _METHOD)
    fits = [s for s in own if _fits(self._scope(s), arity)]
    if fits:
        return fits

        return fits
    supers, complete = self._supertypes(site)
    found: list[Site] = []
    for s in supers:
        inherited = self._methods(s, name, arity, done)
        if inherited is None:
            return None
        found.extend(inherited)
    if found:
        return sorted(set(found))
    implicit = _IMPLICIT.get(scope.decl.kind, _OBJECT)
    if scope.decl.kind == "record":
        implicit = implicit | scope.bound.keys()  # component accessors
    return [] if complete and not own and name not in implicit else None

def _field(self, site: Site, name: str, seen: set[Site]) -> Variable | Found:
    """Field ``name`` of a type, declared or inherited; [] when certainly none. A
    local or anonymous class body's variables are its fields and locals together."""
    scope = self._scope(site)
    if name in scope.bound:
        return site, scope.bound[name]
    if site in seen:
        return None
    seen.add(site)
    supers, complete = self._supertypes(site)
    for s in supers:
        found = self._field(s, name, seen)
        if found != []:
            return found
    return [] if complete else None

def _variable(self, i: int, k: int, name: str) -> Variable | Found:
    """The variable ``name`` denotes in scope ``k``; [] when it is no variable."""
    scopes = self.files[i].parsed.scopes
    while k:
        scope = scopes[k]
        if _is_type(scope):
            found = self._field((i, k), name, set())
            if found != []:
                return found
        elif name in scope.bound:
            return (i, k), scope.bound[name]
        k = scope.parent or 0
    file = self.files[i]
    if name in file.statics or any(
        self._field(s, name, set()) not in ([], None) for s in file.static_demand
    ):
        return None  # a statically imported field
    return []

def _on(self, types: Found, name: str, arity: int) -> Found:
    """Methods ``name`` of any of ``types``."""
    found: list[Site] = []
    for t in types or []:
        methods = self._methods(t, name, arity, {})
        if methods is None:
            return None
        found.extend(methods)
    return sorted(set(found)) or None

def _call(self, i: int, k: int, call: Call) -> Found:
    if call.name.startswith("new "):
        return self._type(i, k, call.name[4:])
    file = self.files[i]
    scopes = file.parsed.scopes
    qualifier, _, name = call.name.rpartition(".")
    if not qualifier:
        at = k
        while at:
            if _is_type(scopes[at]):
                found = self._methods((i, at), name, call.arity, {})
                if found is None or found:
                    return found
            at = scopes[at].parent or 0
        return self._on(file.statics.get(name, file.static_demand), name, call.arity)
    inner = k

                if found is None or found:
                    return found
            at = scopes[at].parent or 0
        return self._on(file.statics.get(name, file.static_demand), name, call.arity)
    inner = k
    while inner and not _is_type(scopes[inner]):
        inner = scopes[inner].parent or 0
    if not inner:
        return None
    if qualifier == "this":
        return self._on([(i, inner)], name, call.arity)
    if qualifier == "super":
        supers, complete = self._supertypes((i, inner))
        return self._on(supers, name, call.arity) if complete else None
    if qualifier.startswith("this."):
        variable = self._field((i, inner), qualifier[5:], set())
    else:
        first, dot, _ = qualifier.partition(".")
        variable = self._variable(i, k, first)
        if variable == []:  # a type (a static method), or a type's static field
            types = self._type(i, k, qualifier)
            owner, _, member = qualifier.rpartition(".")
            owners = None if types or not dot else self._type(i, k, owner)
            if owners is None or len(owners) != 1:
                return self._on(types, name, call.arity)
            variable = self._field(owners[0], member, set())
        elif dot:
            return None  # a field of a variable: needs its type's fields
    if not isinstance(variable, tuple):
        return None
    (vi, vk), kind = variable
    return None if kind is None else self._on(self._type(vi, vk, kind), name, call.arity)

# --- imports and edges ---

def _bind_imports(self, file: _File) -> None:
    for item in file.parsed.imports:
        path = item.path
        if item.static:
            owner, _, member = path.rpartition(".")
            owners = self._canonical(path if item.wildcard else owner)
            if item.wildcard:
                file.static_demand.extend(owners)
            else:
                file.statics.setdefault(member, []).extend(owners)
        elif item.wildcard:
            package = ("", path) in self.packages
            file.demand.extend([path] if package else self._canonical(path))
        else:
            file.single.setdefault(path.rpartition(".")[2], []).extend(self._canonical(path))

def _import_targets(self, path: str, static: bool, wildcard: bool) -> list[str]:
    """What an import names: a package's module, a type, or a static member (a
    method or member type; the owner type for a field)."""
    if wildcard and not static and ("", path) in self.packages:
        return [module_key(path)]
    if wildcard or not static:
        return self._keys(self._canonical(path))
    owner, _, member = path.rpartition(".")
    owners = self._canonical(owner)
    named = [m for o in owners for m in self._declared(o, member, _IMPORTABLE)]
    return self._keys(named or [o for o in owners if member in self._scope(o).bound])

def _keys(self, sites: list[Site]) -> list[str]:
    return sorted({str(self.files[i].keys[k]) for i, k in sites})

    return sorted({str(self.files[i].keys[k]) for i, k in sites})

def derive(self, entities: list[Entity], edges: list[Edge]) -> None:
    for package in sorted(p for p in self.packages if p[1]):
        key = module_key(package[1])
        entities.append(Entity(key, "module", "module", package[1], None, None, False))
        edges.append(structural("contains", "repo", key, None))
        for i in self.packages[package]:
            file_key = f"file:{self.files[i].path}"
            edges.append(structural("contains_logical", key, file_key, None))
    for i in range(len(self.files)):
        self._emit(i, entities, edges)

def _emit(self, i: int, entities: list[Entity], edges: list[Edge]) -> None:
    file = self.files[i]

    def evidence(start: int, end: int) -> SourceRef:
        return SourceRef(file.path, start, end, file.digest)

    def edge(kind: RelationKind, source: str, res: Res, use: Use | Call) -> Edge:
        targets, resolution, basis = edge_target(res, kind == "calls")
        shown = None if resolution == "resolved" else use.name
        at = evidence(use.start, use.end)
        return Edge(kind, source, targets, resolution, basis, shown, at)

    for item in file.parsed.imports:
        res = self._import_targets(item.path, item.static, item.wildcard) or None
        edges.append(edge("imports", file.owners[0], res, Use(item.path, item.start, item.end)))

    # A declaration's modifiers lie in its parent scope (java._Facts._open) yet are its own.
    heads: dict[int, list[tuple[int, int, int]]] = {}
    for k, scope in enumerate(file.parsed.scopes):
        if k and scope.decl is not None and scope.parent is not None:
            heads.setdefault(scope.parent, []).append((scope.decl.start, scope.decl.end, k))

    def owner(k: int, at: int) -> str:
        row = heads.get(k, [])
        j = bisect.bisect_right(row, (at + 1,)) - 1
        return file.owners[row[j][2] if j >= 0 and at < row[j][1] else k]

    for k, scope in enumerate(file.parsed.scopes):
        key = file.keys[k]
        if k and key is not None and scope.decl is not None:
            d = scope.decl
            at = evidence(d.start, d.end)
            entities.append(Entity(key, "symbol", d.kind, d.name, d.signature, at, d.test))
            edges.append(structural("contains", file.owners[scope.parent or 0], key, None))
            if scope.parent == 0 and file.package[1]:
                edges.append(structural("defines", module_key(file.package[1]), key, at))
        for ref in scope.refs:
            found = self._type(i, k, ref.name)
            source = owner(k, ref.start)
            edges.append(edge("references", source, self._keys(found or []) or None, ref))
        for call in scope.calls:
            found = self._call(i, k, call)
            source = owner(k, call.start)
            relation = edge("calls", source, self._keys(found or []) or None, call)
            callee = relation.targets[0] if relation.resolution == "resolved" else None
            if source in self.tests and callee and callee not in self.tests:
                at = evidence(call.start, call.end)
                edges.append(
                    Edge("tested_by", callee, (source,), "resolved", "heuristic", None, at)
                )
            edges.append(relation)

